   hp:st.party.map(p=>Math.round(p.hp*10)/10),
   skills:st.skills.map(x=>x?x.id+':'+x.remainingTicks:null),
   bench:st.build.bench.map(b=>b.node),
   sockets:st.build.skills.flatMap(sk=>sk.sockets.filter(Boolean).map(x=>sk.id+'/'+x.node)),
